package com.bank.sqtypes.service;

import com.bank.sqtypes.model.*;
import java.math.*;
import java.util.*;
import java.util.logging.Logger;

public class SubqueryTypes {
    private static final Logger log = Logger.getLogger(SubqueryTypes.class.getName());
    private final List<Account> accounts;
    private final List<Txn> txns;

    public SubqueryTypes(List<Account> accounts, List<Txn> txns) { this.accounts = accounts; this.txns = txns; }

    // SCALAR: one value (avg balance) used in a WHERE comparison.
    public List<Account> aboveAverageBalance() {
        BigDecimal avg = accounts.stream().map(Account::getBalance)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .divide(BigDecimal.valueOf(accounts.size()), 2, RoundingMode.HALF_UP);
        log.info(() -> "SCALAR subquery value (avg balance) = " + avg);
        List<Account> r = new ArrayList<>();
        for (Account a : accounts) if (a.getBalance().compareTo(avg) > 0) r.add(a);
        return r;
    }

    // ROW: match a (city, type) tuple from a reference account.
    public List<Account> sameCityAndTypeAs(String refId) {
        Account ref = accounts.stream().filter(a -> a.getId().equals(refId)).findFirst().orElseThrow();
        log.info(() -> "ROW subquery tuple = (" + ref.getCity() + ", " + ref.getType() + ")");
        List<Account> r = new ArrayList<>();
        for (Account a : accounts)
            if (!a.getId().equals(refId) && a.getCity().equals(ref.getCity()) && a.getType().equals(ref.getType())) r.add(a);
        return r;
    }

    // TABLE (inline view): stage per-account totals, then filter big spenders.
    public Map<String, BigDecimal> bigSpenders(BigDecimal threshold) {
        Map<String, BigDecimal> totals = new LinkedHashMap<>();          // the derived table
        for (Txn t : txns) totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        log.info(() -> "TABLE subquery (inline view) staged totals = " + totals);
        Map<String, BigDecimal> r = new LinkedHashMap<>();
        totals.forEach((k, v) -> { if (v.compareTo(threshold) > 0) r.put(k, v); });
        return r;
    }

    // CORRELATED: transactions above their OWN account's average.
    public List<Long> aboveOwnAccountAverage() {
        List<Long> r = new ArrayList<>();
        for (Txn t : txns) {                                            // correlated: inner depends on t
            List<BigDecimal> same = txns.stream().filter(x -> x.getAccountId().equals(t.getAccountId()))
                    .map(Txn::getAmount).toList();
            BigDecimal avg = same.stream().reduce(BigDecimal.ZERO, BigDecimal::add)
                    .divide(BigDecimal.valueOf(same.size()), 2, RoundingMode.HALF_UP);
            if (t.getAmount().compareTo(avg) > 0) r.add(t.getId());
        }
        log.info(() -> "CORRELATED subquery result ids = " + r);
        return r;
    }
}
