package com.bank.sqtypes;

import com.bank.sqtypes.model.*;
import com.bank.sqtypes.service.SubqueryTypes;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SubqueryTypesDemo {
    private static final Logger log = Logger.getLogger(SubqueryTypesDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        List<Account> accounts = List.of(
            new Account("SAV2001","Delhi","SAVINGS", new BigDecimal("1000000")),
            new Account("CUR3001","Delhi","SAVINGS", new BigDecimal("250000")),
            new Account("CUR3002","Mumbai","CURRENT", new BigDecimal("50000")));
        List<Txn> txns = List.of(
            new Txn(1,"SAV2001", new BigDecimal("900000")),
            new Txn(2,"SAV2001", new BigDecimal("200000")),
            new Txn(3,"CUR3001", new BigDecimal("60000")),
            new Txn(4,"CUR3001", new BigDecimal("20000")));
        SubqueryTypes svc = new SubqueryTypes(accounts, txns);

        log.info("=== SCALAR: accounts above average balance ===");
        svc.aboveAverageBalance().forEach(a -> log.info("  " + a.getId()));
        log.info("=== ROW: same (city,type) as SAV2001 ===");
        svc.sameCityAndTypeAs("SAV2001").forEach(a -> log.info("  " + a.getId()));
        log.info("=== TABLE: big spenders over Rs.10,00,000 ===");
        log.info("  " + svc.bigSpenders(new BigDecimal("1000000")));
        log.info("=== CORRELATED: txns above own account avg ===");
        svc.aboveOwnAccountAverage();
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

